gMz(){return"\u041d\u043e\u0432\u0456 \u0433\u0440\u0443\u043f\u0438 \u043c\u043e\u0436\u0435 \u0441\u0442\u0432\u043e\u0440\u044e\u0432\u0430\u0442\u0438 \u043b\u0438\u0448\u0435 \u0430\u0434\u043c\u0456\u043d\u0456\u0441\u0442\u0440\u0430\u0442\u043e\u0440 \u043a\u043b\u0443\u0431\u0443. \u0417\u0432\u0435\u0440\u043d\u0456\u0442\u044c\u0441\u044f \u0434\u043e \u043d\u044c\u043e\u0433\u043e \u0430\u0431\u043e \u0456\u043c\u043f\u043e\u0440\u0442\u0443\u0439\u0442\u0435 \u0432 \u043d\u0430\u044f\u0432\u043d\u0443 \u0433\u0440\u0443\u043f\u0443 (\u0413\u0440\u0443\u043f\u0430 \u2192 \u043c\u0435\u043d\u044e \u2192 \u0406\u043c\u043f\u043e\u0440\u0442)."},
gMI(){return"\u0423 \u0440\u044f\u0434\u043a\u0443 \u043d\u0435\u043c\u0430\u0454 \u0433\u0440\u0443\u043f\u0438, \u043f\u0440\u043e\u043f\u0443\u0449\u0435\u043d\u043e"},
